--
-- Name: a2a_reply agentcanvas_tenant; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY agentcanvas_tenant ON public.a2a_reply USING (((current_setting('agentcanvas.all_tenants'::text, true) = 'on'::text) OR (EXISTS ( SELECT 1
   FROM public.thread p
  WHERE ((p.id)::text = (a2a_reply.thread_id)::text)))));

